import { banglaDigits } from "./bangla";
import bnCopy from "./generated/copy.bn.json";
import enCopy from "./generated/copy.en.json";
import type { Lang } from "./lang";

/*
 * The one door to copy (eslint bans importing copy/generated/* from anywhere but src/copy/**). The JSON is generated by
 * baymax WebCopyExportTest from the same bundles the Java pages render, so React renders Java's words and never
 * derives its own.
 */

export type { Lang } from "./lang";
export { langOf } from "./lang";
export { banglaDigits, formatDate, formatDayMonth, formatMonthYear, formatPrinted, formatTime } from "./bangla";

export type CopyKey = Exclude<keyof typeof bnCopy, "_meta">;

const COPY: Record<Lang, Record<string, unknown>> = { bn: bnCopy, en: enCopy };

/**
 * The string for `key` in `lang`, with `{i}` replaced by `args[i]`, exactly as UiCopy.raw does it: on bn a `number`
 * argument (an age, a count) is written in Bangla digits; a `string` argument is kept as it is, so a value read off the
 * paper keeps the digits printed on it. An unknown key throws. No HTML escaping: React escapes.
 */
export function t(lang: Lang, key: CopyKey, ...args: Array<string | number>): string {
  const raw = key === ("_meta" as string) ? undefined : COPY[lang][key];
  if (typeof raw !== "string") throw new Error(`no copy for key ${key}`);
  let out = raw;
  args.forEach((arg, i) => {
    const text = lang === "bn" && typeof arg === "number" ? banglaDigits(String(arg)) : String(arg);
    out = out.replaceAll(`{${i}}`, text);
  });
  return out;
}
